    <p v-if="!editable && sheet.confirmedAt" class="confirmed-note">{{ sheet.confirmedBy }} · {{ sheet.confirmedAt }}<template v-if="sheet.reason"> · {{ sheet.reason }}</template></p>
  </section>
</template>

